//go:build ignore

// gen-tables regenerates the resource and data source tables in AGENTS.md and
// README.md from the provider registry and the generated docs. Run it through
// `make generate-tables`; it is idempotent and only writes a file when the
// generated bytes differ.
//
// The description of each type comes from the `description:` front matter of
// its generated docs page, so the docs stay the single source of truth for
// what a type does. The Go file come from provider.RegistrySnapshot(), which
// resolves it from the registered factory, so there is no hand-maintained
// type-to-file mapping.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/caberdo/terraform-provider-rustfs/provider"
)

const (
	resourceDocsDir   = "docs/resources"
	dataSourceDocsDir = "docs/data-sources"
	registryURL       = "https://registry.terraform.io/providers/caberdo/rustfs/latest/docs"
)

type marker struct {
	begin string
	end   string
}

var (
	resourcesMarker   = marker{"<!-- BEGIN AUTOGEN:resources -->", "<!-- END AUTOGEN:resources -->"}
	dataSourcesMarker = marker{"<!-- BEGIN AUTOGEN:data-sources -->", "<!-- END AUTOGEN:data-sources -->"}
	countsMarker      = marker{"<!-- BEGIN AUTOGEN:counts -->", "<!-- END AUTOGEN:counts -->"}
)

func main() {
	root := flag.String("root", ".", "repository root")
	flag.Parse()

	if err := run(*root); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(root string) error {
	entries := provider.RegistrySnapshot()
	if len(entries) == 0 {
		return errors.New("the provider registry is empty")
	}

	var problems []string
	descriptions := make(map[string]string, len(entries))
	for _, entry := range entries {
		name, ok := strings.CutPrefix(entry.TypeName, "rustfs_")
		if !ok {
			problems = append(problems, fmt.Sprintf("%s: type name does not start with rustfs_", entry.TypeName))
			continue
		}

		docsPath := filepath.Join(resourceDocsDir, name+".md")
		if entry.Kind == provider.RegistryKindDataSource {
			docsPath = filepath.Join(dataSourceDocsDir, name+".md")
		}

		description, err := docsDescription(filepath.Join(root, docsPath))
		if err != nil {
			problems = append(problems, fmt.Sprintf("%s: %v", entry.TypeName, err))
			continue
		}
		descriptions[descriptionKey(entry)] = description

		if entry.File == "" {
			problems = append(problems, fmt.Sprintf("%s: the source file could not be resolved from its factory", entry.TypeName))
			continue
		}
		if _, err := os.Stat(filepath.Join(root, entry.File)); err != nil {
			problems = append(problems, fmt.Sprintf("%s: source file %s: %v", entry.TypeName, entry.File, err))
		}
	}
	if len(problems) > 0 {
		return fmt.Errorf("cannot generate tables:\n  %s", strings.Join(problems, "\n  "))
	}

	if err := rewrite(filepath.Join(root, "AGENTS.md"), entries, descriptions, agentsTable); err != nil {
		return err
	}
	if err := rewrite(filepath.Join(root, "README.md"), entries, descriptions, readmeTable); err != nil {
		return err
	}
	return nil
}

// rewrite replaces the resource, data source and count regions of one file.
func rewrite(path string, entries []provider.RegistryEntry, descriptions map[string]string, table func(provider.RegistryKind, string, []provider.RegistryEntry, map[string]string) string) error {
	original, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	content := string(original)
	content, err = replaceRegion(content, resourcesMarker, table(provider.RegistryKindResource, "resources", entries, descriptions))
	if err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	content, err = replaceRegion(content, dataSourcesMarker, table(provider.RegistryKindDataSource, "data-sources", entries, descriptions))
	if err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	if strings.Contains(content, countsMarker.begin) {
		content, err = replaceRegion(content, countsMarker, counts(entries))
		if err != nil {
			return fmt.Errorf("%s: %w", path, err)
		}
	}

	if content == string(original) {
		return nil
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

func replaceRegion(content string, m marker, body string) (string, error) {
	if strings.Count(content, m.begin) != 1 || strings.Count(content, m.end) != 1 {
		return "", fmt.Errorf("expected exactly one %q and one %q marker", m.begin, m.end)
	}

	start := strings.Index(content, m.begin) + len(m.begin)
	end := strings.Index(content, m.end)
	if end < start {
		return "", fmt.Errorf("%q appears before %q", m.end, m.begin)
	}

	body = strings.Trim(body, "\n")
	if body != "" {
		body = "\n" + body + "\n"
	}
	return content[:start] + body + content[end:], nil
}

func agentsTable(kind provider.RegistryKind, _ string, entries []provider.RegistryEntry, descriptions map[string]string) string {
	if kind == provider.RegistryKindDataSource {
		return renderTable("| Type | Returns | Source |", entries, descriptions, kind, func(entry provider.RegistryEntry) []string {
			return []string{"`" + entry.TypeName + "`", descriptions[descriptionKey(entry)], "`" + entry.File + "`"}
		})
	}
	return renderTable("| Type | Manages | Source |", entries, descriptions, kind, func(entry provider.RegistryEntry) []string {
		return []string{"`" + entry.TypeName + "`", descriptions[descriptionKey(entry)], "`" + entry.File + "`"}
	})
}

func readmeTable(kind provider.RegistryKind, segment string, entries []provider.RegistryEntry, descriptions map[string]string) string {
	header := "| Resource | Manages |"
	if kind == provider.RegistryKindDataSource {
		header = "| Data source | Returns |"
	}
	return renderTable(header, entries, descriptions, kind, func(entry provider.RegistryEntry) []string {
		name := strings.TrimPrefix(entry.TypeName, "rustfs_")
		link := "[" + "`" + entry.TypeName + "`" + "](" + registryURL + "/" + segment + "/" + name + ")"
		return []string{link, descriptions[descriptionKey(entry)]}
	})
}

func renderTable(header string, entries []provider.RegistryEntry, descriptions map[string]string, kind provider.RegistryKind, row func(provider.RegistryEntry) []string) string {
	columns := strings.Count(header, "|") - 1
	lines := []string{header, "|" + strings.Repeat("---|", columns)}

	for _, entry := range entries {
		if entry.Kind != kind {
			continue
		}
		cells := row(entry)
		if len(cells) != columns {
			panic("table row does not match the header")
		}
		lines = append(lines, "| "+strings.Join(cells, " | ")+" |")
	}
	return strings.Join(lines, "\n")
}

// descriptionKey scopes a description to a kind, because one type name can be
// both a resource and a data source (rustfs_quota).
func descriptionKey(entry provider.RegistryEntry) string {
	return string(entry.Kind) + "/" + entry.TypeName
}

func counts(entries []provider.RegistryEntry) string {
	var resources, dataSources int
	for _, entry := range entries {
		switch entry.Kind {
		case provider.RegistryKindResource:
			resources++
		case provider.RegistryKindDataSource:
			dataSources++
		}
	}
	return fmt.Sprintf("**%d resources and %d data sources.**", resources, dataSources)
}

// docsDescription reads and normalises the description front matter of a
// generated docs page into one table cell.
func docsDescription(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("no docs page: %w", err)
	}

	description, err := frontMatterDescription(string(data))
	if err != nil {
		return "", fmt.Errorf("%s: %w", path, err)
	}

	description = strings.Join(strings.Fields(description), " ")
	if description == "" {
		return "", fmt.Errorf("%s: the description front matter is empty", path)
	}
	return strings.ReplaceAll(description, "|", `\|`), nil
}

func frontMatterDescription(content string) (string, error) {
	lines := strings.Split(content, "\n")
	if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
		return "", errors.New("missing YAML front matter")
	}

	end := -1
	for i := 1; i < len(lines); i++ {
		if strings.TrimSpace(lines[i]) == "---" {
			end = i
			break
		}
	}
	if end < 0 {
		return "", errors.New("unterminated YAML front matter")
	}

	for i := 1; i < end; i++ {
		line := lines[i]
		if !strings.HasPrefix(line, "description:") {
			continue
		}

		value := strings.TrimSpace(strings.TrimPrefix(line, "description:"))
		if value != "" && value != "|" && value != "|-" && value != ">" && value != ">-" {
			return strings.Trim(value, `"'`), nil
		}

		var block []string
		for j := i + 1; j < end; j++ {
			next := lines[j]
			if next != "" && !strings.HasPrefix(next, " ") && !strings.HasPrefix(next, "\t") {
				break
			}
			block = append(block, next)
		}
		return strings.Join(block, "\n"), nil
	}

	return "", errors.New("the front matter has no description")
}
